INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, is_indexed, status, attribution_type, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Motor DC biasa tidak bisa berhenti tepat pada posisi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Motor DC berputar bebas, sehingga sulit dipakai untuk menunjuk sudut tertentu, menggeser print head, atau memutar kamera sedikit demi sedikit. Motor stepper memecahkan masalah ini: ia bergerak dalam langkah-langkah kecil yang terukur, misalnya 1,8 derajat per langkah pada NEMA 17 atau 5,625 derajat pada 28BYJ-48. Setiap pulsa listrik memutar rotor satu langkah pasti.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: cara kerja stepper dan mode penggerak$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Di dalam stepper ada beberapa kumparan (koil) yang diaktifkan bergantian oleh driver, menarik rotor magnetis selangkah demi selangkah. Urutan aktifasi koil menentukan arah putar, sedangkan kecepatan pulsa menentukan kecepatan putar. Driver ULN2003 memudahkan karena Arduino hanya memberi sinyal logika, bukan arus besar. Kelemahannya: torsi turun pada kecepatan tinggi dan motor tetap menarik arus saat diam.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Persiapan alat dan bahan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Arduino Uno/Nano$txt$, $txt$Motor stepper 28BYJ-48 + driver ULN2003 (satu paket)$txt$, $txt$Kabel jumper male-female$txt$, $txt$Catu daya 5V eksternal 1A (opsional, disarankan)$txt$, $txt$Kabel USB ke komputer$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah-langkah$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Rangkai kabel: sambungkan IN1-IN4 driver ULN2003 ke pin digital 8, 9, 10, 11 Arduino; VCC ke 5V dan GND ke GND; colokkan konektor motor ke driver.$txt$, $txt$Program gerakan dasar: gunakan pustaka Stepper bawaan Arduino IDE; buat objek Stepper(2048, 8, 10, 9, 11) — 2048 langkah per putaran 28BYJ-48; panggil stepper.setSpeed(10) lalu stepper.step(2048) untuk satu putaran, nilai negatif untuk arah sebaliknya.$txt$, $txt$Kendalikan sudut dan kecepatan: hitung langkah = (sudut/360) x 2048 (misalnya 90 derajat = 512 langkah); atur kecepatan 5-15 RPM agar torsi cukup; tambahkan tombol atau potensiometer sebagai masukan interaktif.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan hal yang perlu diwaspadai$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Jangan putar rotor paksa dengan tangan saat motor aktif — arus balik bisa merusak driver$txt$, $txt$Pastikan tegangan catu sesuai spesifikasi motor (28BYJ-48 = 5V); tegangan berlebih membuat motor panas$txt$, $txt$Motor tetap hangat saat menahan posisi — normal, tetapi beri jeda bila terlalu panas$txt$, $txt$Stepper berisik pada kecepatan tertentu — pilih kecepatan yang halus$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Pemeriksaan hasil dan tindak lanjut$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Motor harus berputar satu putaran penuh saat stepper.step(2048), berbalik arah saat nilainya negatif, dan berhenti tepat tanpa meluncur. Tandai poros dengan spidol; posisi berhenti harus bisa diulang dengan presisi. Jika motor hanya bergetar, periksa urutan kabel IN1-IN4. Setelah dasar dikuasai, kembangkan ke proyek nyata: slider kamera time-lapse, lengan robot sederhana, atau pengatur tirai otomatis; untuk torsi besar naik ke NEMA 17 + driver A4988/DRV8825 dengan catu 12V.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, is_indexed, status, attribution_type, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: buntut alot dan kuah keruh$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Buntut sapi kaya kolagen sehingga berpotensi sangat empuk, tetapi salah masak membuatnya alot dan kuahnya keruh berlemak. Kunci sop buntut Jakarta adalah kuah bening yang gurih, daging empuk lepas dari tulang, dan aroma rempah yang hangat tanpa amis.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: kenapa buntut perlu dimasak lama$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Kolagen pada buntut berubah menjadi gelatin saat direbus perlahan minimal 2–3 jam, inilah yang membuat daging empuk dan kuah terasa kaya. Merebus dengan api kecil mencegah lemak tercampur (emulsi) sehingga kuah tetap bening. Bumbu seperti pala, cengkeh, dan kayu manis memberi aroma khas sop buntut Jakarta.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Persiapan bahan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$1 kg buntut sapi, potong per ruas$txt$, $txt$2 liter air$txt$, $txt$3 siung bawang putih, memarkan$txt$, $txt$1 buah bawang bombai, iris$txt$, $txt$2 cm jahe, memarkan$txt$, $txt$1/2 sdt pala bubuk$txt$, $txt$3 butir cengkeh$txt$, $txt$2 cm kayu manis$txt$, $txt$Garam, gula, dan merica secukupnya$txt$, $txt$2 batang daun bawang + seledri, iris$txt$, $txt$Bawang goreng dan jeruk nipis untuk pelengkap$txt$, $txt$Kentang dan wortel potong (opsional)$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah-langkah$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Rebus awal: rebus buntut dalam air mendidih 10 menit, buang airnya, dan bilas buntut untuk menghilangkan kotoran dan bau amis; masukkan ke panci berisi 2 liter air bersih yang baru.$txt$, $txt$Rebus perlahan dengan rempah: masukkan bawang putih, bawang bombai, jahe, pala, cengkeh, dan kayu manis; didihkan lalu kecilkan api dan rebus 2,5-3 jam dengan tutup sedikit terbuka; buang busa di permukaan; daging empuk jika mudah ditusuk garpu.$txt$, $txt$Bumbui dan sajikan: tambahkan garam, gula, dan merica; koreksi rasa hingga gurih seimbang; masukkan kentang dan wortel 30 menit sebelum diangkat bila dipakai; sajikan panas dengan taburan daun bawang, seledri, bawang goreng, dan perasan jeruk nipis.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan hal yang perlu diwaspadai$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Api terlalu besar membuat kuah keruh dan daging menyusut$txt$, $txt$Jangan tambah air dingin di tengah perebusan — gunakan air panas agar suhu stabil$txt$, $txt$Buntut berlemak; dinginkan kuah semalam dan buang lemak beku bila ingin lebih ringan$txt$, $txt$Simpan sisa maksimal 2 hari di kulkas, panaskan sampai mendidih sebelum disajikan ulang$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Pemeriksaan hasil dan tindak lanjut$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Kuah bening kekuningan dan gurih, daging empuk lepas dari tulang tanpa hancur, aroma rempah terasa tetapi tidak menyengat. Jika kuah hambar, tambahkan garam sedikit demi sedikit; jika berminyak, serok permukaan dengan sendok sayur. Variasikan dengan sop buntut goreng atau sop buntut bakar; sisa kuah bisa dipakai sebagai kaldu sup lain.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, is_indexed, status, attribution_type, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Logam yang bisa dipotong pisau$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Natrium adalah logam berwarna keperakan yang sangat lunak — bisa dipotong dengan pisau dapur. Ia termasuk golongan logam alkali (golongan 1 tabel periodik) dengan simbol Na dari bahasa Latin natrium. Saking reaktifnya, natrium murni tidak pernah ditemukan bebas di alam; ia selalu terikat dalam senyawa.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Reaksi dramatis dengan air$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Potongan kecil natrium yang dimasukkan ke air akan bereaksi hebat: mendesis, meleleh menjadi bola mengkilap yang berlari di permukaan air, dan bisa menyala dengan api kuning. Reaksinya menghasilkan gas hidrogen dan larutan natrium hidroksida yang bersifat basa kuat. Demonstrasi ini hanya boleh dilakukan guru di laboratorium dengan alat pelindung.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Garam dapur: senyawa natrium paling terkenal$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Natrium klorida (NaCl) alias garam dapur adalah senyawa natrium yang paling akrab. Tubuh membutuhkan natrium dalam jumlah kecil untuk mengatur cairan dan kerja saraf, tetapi kelebihan garam dikaitkan dengan tekanan darah tinggi. Sebagian besar natrium yang kita konsumsi berasal dari makanan olahan, bukan dari garam yang ditaburkan sendiri.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Senyawa natrium dalam kehidupan sehari-hari$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Selain garam dapur, ada natrium bikarbonat (soda kue untuk pengembang kue dan penghilang bau), natrium hidroksida (soda api untuk sabun dan pembersih), serta natrium karbonat (soda abu untuk kaca dan deterjen). Hampir semua sabun dan deterjen modern melibatkan senyawa natrium dalam pembuatannya.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Lampu natrium yang kuning terang$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Lampu uap natrium menghasilkan cahaya kuning-oranye yang sangat terang dan hemat energi, sehingga dulu banyak dipakai untuk lampu jalan. Cahaya monokromatiknya juga dimanfaatkan di laboratorium untuk kalibrasi alat optik. Kini lampu ini perlahan digantikan lampu LED yang lebih efisien.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, is_indexed, status, attribution_type, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Latar belakang: Asia-Afrika pasca perang dunia$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah Perang Dunia II, banyak bangsa Asia dan Afrika baru merdeka dari penjajahan tetapi masih menghadapi tekanan kolonialisme dan tarik-menarik Perang Dingin antara blok Barat dan blok Timur. Para pemimpin Asia mulai menjajaki kerja sama agar suara negara-negara baru merdeka diperhitungkan dunia.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Dari Konferensi Kolombo ke Bandung$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Gagasan konferensi besar Asia-Afrika lahir dari pertemuan lima perdana menteri (Indonesia, India, Pakistan, Burma, dan Sri Lanka) di Kolombo, Sri Lanka, pada 1954. Indonesia menawarkan diri menjadi tuan rumah, dan Bandung dipilih sebagai kota penyelenggara pada 18–24 April 1955.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$29 negara berkumpul di Gedung Merdeka$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Sebanyak 29 negara Asia dan Afrika hadir, mewakili lebih dari separuh penduduk dunia saat itu. Tokoh-tokoh besar seperti Soekarno (Indonesia), Nehru (India), Nasser (Mesir), Zhou Enlai (Tiongkok), dan Nkrumah (Ghana) duduk bersama membahas nasib bangsa-bangsa yang baru merdeka.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Dasasila Bandung: sepuluh prinsip perdamaian$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Hasil terpenting konferensi adalah Dasasila Bandung — sepuluh prinsip yang mencakup penghormatan hak asasi manusia, pengakuan kedaulatan dan keutuhan wilayah, penyelesaian sengketa secara damai, serta penolakan kolonialisme dalam segala bentuk. Prinsip-prinsip ini menjadi fondasi politik luar negeri bebas aktif Indonesia.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Warisan: Gerakan Non-Blok dan solidaritas Selatan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Semangat Bandung melahirkan Gerakan Non-Blok pada 1961 sebagai wadah negara-negara yang tidak memihak blok Barat maupun Timur. Konferensi Asia Afrika diperingati ulang pada 2005 dan 2015 di Bandung, dan Gedung Merdeka kini menjadi Museum Konferensi Asia Afrika yang bisa dikunjungi publik.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, is_indexed, status, attribution_type, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah mempelajari materi ini, peserta didik diharapkan mampu: (1) menjelaskan pengertian dan fungsi peta; (2) mengidentifikasi unsur-unsur peta; (3) membedakan jenis-jenis peta; (4) membaca informasi dari peta dengan benar.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Pengertian dan fungsi peta$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Peta adalah gambaran konvensional permukaan bumi pada bidang datar dengan skala tertentu melalui sistem proyeksi. Fungsi peta antara lain: menunjukkan lokasi, mengukur jarak dan luas, menyajikan data, serta membantu perencanaan (misalnya tata ruang kota). Peta disebut bahasa geografi karena hampir semua kajian geografi memakai peta.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Unsur-unsur peta$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Judul peta — menjelaskan isi/tema peta$txt$, $txt$Skala — perbandingan jarak di peta dengan jarak sebenarnya (angka, garis, atau inci)$txt$, $txt$Orientasi/mata angin — penunjuk arah utara$txt$, $txt$Legenda — keterangan simbol-simbol$txt$, $txt$Simbol — titik, garis, dan area untuk objek$txt$, $txt$Garis lintang dan bujur — koordinat lokasi$txt$, $txt$Inset — peta penyisip untuk konteks$txt$, $txt$Lettering — tata penulisan nama objek$txt$, $txt$Tepi peta dan warna$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Jenis-jenis peta$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Berdasarkan isinya, peta dibagi menjadi peta umum (misalnya peta topografi yang menggambarkan relief) dan peta tematik/khusus (misalnya peta curah hujan, peta kepadatan penduduk, peta geologi). Berdasarkan skalanya ada peta kadaster (sangat detail), peta besar, sedang, kecil, hingga peta geografis (skala sangat kecil, misalnya peta dunia).$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Contoh: membaca peta$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Perhatikan peta provinsi: judulnya 'Peta Administrasi Provinsi X'. Skala 1:1.000.000 artinya 1 cm di peta = 10 km di lapangan. Simbol garis merah tebal adalah jalan arteri, area hijau adalah hutan. Dengan legenda, kita bisa tahu ibu kota provinsi, batas kabupaten, dan sungai-sungai utama tanpa harus datang ke lokasi.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan dan kunci jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Sebutkan 5 unsur peta beserta fungsinya! (Judul=isi peta, skala=perbandingan jarak, orientasi=arah, legenda=keterangan simbol, garis lintang-bujur=koordinat)$txt$, $txt$Apa perbedaan peta umum dan peta tematik? Beri contoh masing-masing! (Umum: kenampakan umum, contoh topografi; Tematik: satu tema khusus, contoh curah hujan)$txt$, $txt$Skala 1:500.000, jarak di peta 4 cm. Berapa jarak sebenarnya? (4 x 500.000 = 2.000.000 cm = 20 km)$txt$, $txt$Mengapa peta disebut bahasa geografi? (Hampir seluruh kajian geografi disajikan dan dianalisis lewat peta)$txt$, $txt$Jelaskan 3 fungsi simbol dalam peta! (Menunjukkan lokasi objek, membedakan jenis objek, menyederhanakan kenampakan nyata)$txt$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, is_indexed, status, attribution_type, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah mempelajari materi ini, peserta didik diharapkan mampu: (1) menjelaskan pengertian puasa; (2) menyebutkan rukun dan syarat puasa; (3) menyebutkan hal-hal yang membatalkan puasa; (4) menjelaskan hikmah berpuasa dalam kehidupan sehari-hari.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Pengertian puasa$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Puasa menurut bahasa artinya menahan. Menurut istilah, puasa adalah menahan diri dari makan, minum, dan segala yang membatalkan puasa, mulai dari terbit fajar hingga terbenam matahari, dengan niat karena Allah. Puasa Ramadhan hukumnya wajib bagi setiap muslim yang sudah baligh, berdasarkan Al-Qur'an surah Al-Baqarah ayat 183.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Rukun dan syarat puasa$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Rukun 1: Niat — berniat puasa pada malam hari sebelum fajar$txt$, $txt$Rukun 2: Menahan diri dari hal-hal yang membatalkan — sejak terbit fajar sampai terbenam matahari (maghrib)$txt$, $txt$Syarat wajib: beragama Islam, baligh (dewasa), berakal sehat, dan mampu melaksanakan puasa$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Hal-hal yang membatalkan puasa$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Puasa batal jika: makan dan minum dengan sengaja, muntah dengan sengaja, keluar darah haid atau nifas, serta murtad (keluar dari Islam). Anak-anak yang belum baligh belum wajib berpuasa, tetapi sangat baik mulai belajar berlatih puasa setengah hari sebagai pembiasaan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Hikmah berpuasa$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Melatih kesabaran dan pengendalian diri$txt$, $txt$Merasakan lapar sehingga peduli pada orang yang kurang mampu$txt$, $txt$Melatih kejujuran karena hanya Allah yang tahu$txt$, $txt$Menjaga kesehatan dengan pola makan teratur$txt$, $txt$Mendapat pahala dan ampunan dari Allah$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan dan kunci jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Apa pengertian puasa menurut istilah? (Menahan diri dari makan, minum, dan yang membatalkan, dari terbit fajar sampai maghrib, dengan niat karena Allah)$txt$, $txt$Sebutkan 2 rukun puasa! (Niat dan menahan diri dari yang membatalkan)$txt$, $txt$Sebutkan 3 syarat wajib puasa! (Islam, baligh, berakal / mampu)$txt$, $txt$Apa yang dimaksud niat dalam puasa? (Tekad di hati untuk berpuasa esok hari karena Allah)$txt$, $txt$Sebutkan 3 hal yang membatalkan puasa! (Makan/minum sengaja, muntah sengaja, haid/nifas)$txt$, $txt$Sebutkan 2 hikmah berpuasa! (Melatih sabar; peduli pada yang kurang mampu; melatih jujur)$txt$])));
